// Package pricing turns the per-model token counts of internal/agentusage
// into an indicative cost in USD. It ships no price: the table is built from
// the user's configuration (agent_usage.prices), and a model without a rate
// has no cost rather than a zero one.
package pricing

import (
	"fmt"
	"math"
	"sort"
	"strings"

	"github.com/anthnel/devdesk/internal/config"
)

// perMillion is the token count a rate is quoted for.
const perMillion = 1_000_000.0

// Rates is the price of one model, in USD per million tokens.
type Rates struct {
	Input        float64
	Output       float64
	CacheWrite5m float64
	CacheWrite1h float64
	CacheRead    float64
}

// Problem describes a price entry that was left out of the table. Key is the
// user's own spelling of the config key; Reason is meant for a log line.
type Problem struct {
	Key    string
	Reason string
}

// Table maps normalized model names to their rates. The zero value is a
// valid empty table.
type Table struct {
	rates map[string]Rates
}

// Len returns the number of priced models.
func (t Table) Len() int { return len(t.rates) }

// normalize makes a model name comparable: trimmed and lower case.
func normalize(s string) string { return strings.ToLower(strings.TrimSpace(s)) }

// namedRate is one of the five rates of an entry, with its config key.
type namedRate struct {
	name string
	rate config.Rate
	dst  *float64
}

// FromConfig builds a Table from the configured prices. An entry that is
// incomplete, holds a rate that is not a finite non-negative number, or whose
// key collides with another after normalization is left out with a Problem;
// the other entries are unaffected. Problems are sorted by key.
func FromConfig(prices map[string]config.ModelPrice) (Table, []Problem) {
	var problems []Problem
	type candidate struct {
		key   string
		rates Rates
	}
	byNorm := map[string][]candidate{}

	for key, p := range prices {
		norm := normalize(key)
		if norm == "" {
			problems = append(problems, Problem{Key: key, Reason: "empty model name"})
			continue
		}
		r, reason := ratesOf(p)
		if reason != "" {
			problems = append(problems, Problem{Key: key, Reason: reason})
			continue
		}
		byNorm[norm] = append(byNorm[norm], candidate{key: key, rates: r})
	}

	t := Table{}
	for norm, cs := range byNorm {
		if len(cs) > 1 {
			for _, c := range cs {
				problems = append(problems, Problem{
					Key:    c.key,
					Reason: fmt.Sprintf("duplicate of another key once case and spaces are ignored (%q)", norm),
				})
			}
			continue
		}
		if t.rates == nil {
			t.rates = map[string]Rates{}
		}
		t.rates[norm] = cs[0].rates
	}
	sortProblems(problems)
	return t, problems
}

// ratesOf validates the five rates of an entry and returns them, or a reason
// naming the first rate that is unusable.
func ratesOf(p config.ModelPrice) (Rates, string) {
	var r Rates
	list := []namedRate{
		{"input", p.Input, &r.Input},
		{"output", p.Output, &r.Output},
		{"cache_write_5m", p.CacheWrite5m, &r.CacheWrite5m},
		{"cache_write_1h", p.CacheWrite1h, &r.CacheWrite1h},
		{"cache_read", p.CacheRead, &r.CacheRead},
	}
	for _, nr := range list {
		v, state := nr.rate.Value()
		switch {
		case state == config.RateMissing:
			return Rates{}, "incomplete: missing " + nr.name
		case state != config.RateSet:
			return Rates{}, nr.name + " is not a number"
		case math.IsNaN(v) || math.IsInf(v, 0):
			return Rates{}, nr.name + " is not a finite number"
		case v < 0:
			return Rates{}, nr.name + " is negative"
		}
		*nr.dst = v
	}
	return r, ""
}

func sortProblems(ps []Problem) {
	sort.Slice(ps, func(i, j int) bool {
		if ps[i].Key != ps[j].Key {
			return ps[i].Key < ps[j].Key
		}
		return ps[i].Reason < ps[j].Reason
	})
}
package pricing

// dateSuffixLen is the length of a trailing "-YYYYMMDD".
const dateSuffixLen = 9

// Lookup returns the rates of a model. It matches the normalized name
// exactly, then once more without one trailing "-YYYYMMDD". There is no
// prefix matching, and nothing else is stripped ("[1m]", provider
// spellings): a key such as claude-sonnet-5 must never price
// claude-sonnet-5-5.
func (t Table) Lookup(model string) (Rates, bool) {
	name := normalize(model)
	if name == "" {
		return Rates{}, false
	}
	if r, ok := t.rates[name]; ok {
		return r, true
	}
	if base, ok := withoutDate(name); ok {
		if r, ok := t.rates[base]; ok {
			return r, true
		}
	}
	return Rates{}, false
}

// withoutDate removes one trailing "-" plus eight digits.
func withoutDate(name string) (string, bool) {
	n := len(name)
	if n <= dateSuffixLen || name[n-dateSuffixLen] != '-' {
		return "", false
	}
	for i := n - dateSuffixLen + 1; i < n; i++ {
		if name[i] < '0' || name[i] > '9' {
			return "", false
		}
	}
	return name[:n-dateSuffixLen], true
}
package pricing

import (
	"math"
	"sort"

	"github.com/anthnel/devdesk/internal/agentusage"
)

// noModelLabel names the bucket of tokens recorded under no model.
const noModelLabel = "(no model)"

// Status tells what an Estimate holds.
type Status int

const (
	// NoTokens means there was nothing to price; USD is 0 and means nothing.
	NoTokens Status = iota
	// Priced means every model with tokens has a rate; USD is the cost.
	Priced
	// Unpriced means at least one model with tokens has no rate. USD is 0 and
	// must not be shown: a partial sum would under-state without saying so.
	Unpriced
)

// Estimate is the indicative cost of an agent, or of a sum of agents.
type Estimate struct {
	USD    float64
	Status Status
	// Unpriced lists the models with tokens and no rate, in first-appearance
	// order; the bucket of no model is "(no model)".
	Unpriced []string
}

// Cost returns the cost in USD of one model's tokens. The 5 minute cache
// write is the total write minus its 1 hour part.
func (r Rates) Cost(m agentusage.ModelUsage) float64 {
	t := m.Tokens
	return (float64(t.Input)*r.Input +
		float64(t.Output)*r.Output +
		float64(m.CacheWrite5m())*r.CacheWrite5m +
		float64(m.CacheWrite1h)*r.CacheWrite1h +
		float64(t.CacheRead)*r.CacheRead) / perMillion
}

// hasTokens reports whether a model bucket carries any token.
func hasTokens(m agentusage.ModelUsage) bool {
	t := m.Tokens
	return t.Input != 0 || t.Output != 0 || t.CacheRead != 0 || t.CacheWrite != 0
}

// Agent estimates one agent. It never returns a partial cost: one model with
// tokens and no rate makes the whole agent Unpriced.
func (t Table) Agent(a agentusage.Agent) Estimate {
	var e Estimate
	buckets := a.ByModel
	if len(buckets) == 0 && a.Tokens != (agentusage.Tokens{}) {
		// Tokens without a split cannot be priced per model.
		buckets = []agentusage.ModelUsage{{Tokens: a.Tokens}}
	}
	for _, m := range buckets {
		if !hasTokens(m) {
			continue
		}
		e.Status = Priced
		r, ok := t.Lookup(m.Model)
		if !ok {
			e.Unpriced = appendOnce(e.Unpriced, modelLabel(m.Model))
			continue
		}
		cost := r.Cost(m)
		if !isFinite(cost) {
			// A huge rate times a huge count is not a cost worth showing.
			e.Unpriced = appendOnce(e.Unpriced, modelLabel(m.Model))
			continue
		}
		e.USD += cost
	}
	if len(e.Unpriced) > 0 || !isFinite(e.USD) {
		return Estimate{Status: Unpriced, Unpriced: e.Unpriced}
	}
	return e
}

// isFinite reports whether f is neither NaN nor an infinity.
func isFinite(f float64) bool { return !math.IsNaN(f) && !math.IsInf(f, 0) }

func modelLabel(model string) string {
	if model == "" {
		return noModelLabel
	}
	return model
}

func appendOnce(list []string, s string) []string {
	for _, x := range list {
		if x == s {
			return list
		}
	}
	return append(list, s)
}

// Sum adds estimates: Unpriced if any is, NoTokens if all are.
func Sum(es []Estimate) Estimate {
	var out Estimate
	for _, e := range es {
		switch e.Status {
		case Priced:
			out.USD += e.USD
			if out.Status == NoTokens {
				out.Status = Priced
			}
		case Unpriced:
			out.Status = Unpriced
			for _, m := range e.Unpriced {
				out.Unpriced = appendOnce(out.Unpriced, m)
			}
		}
	}
	if !isFinite(out.USD) {
		// The sum of finite estimates can still overflow.
		out.Status = Unpriced
	}
	if out.Status == Unpriced {
		out.USD = 0
	}
	return out
}

// Summary is the cost picture of a whole session.
type Summary struct {
	Agents []Estimate // same order as Usage.Agents
	Billed agentusage.Billed
	// Unattributed is Billed minus the agents' estimates; it may be negative
	// (the price table is higher than what was recorded). It is meaningful
	// only when UnattributedKnown.
	Unattributed      float64
	UnattributedKnown bool
	Unpriced          []string // sorted, distinct, over the whole session
}

// Session estimates every agent of a session. Unattributed is known only when
// Billed is known and every agent with tokens is priced.
func (t Table) Session(u agentusage.Usage) Summary {
	s := Summary{Agents: make([]Estimate, len(u.Agents)), Billed: u.Billed}
	for i, a := range u.Agents {
		s.Agents[i] = t.Agent(a)
	}
	total := Sum(s.Agents)
	s.Unpriced = total.Unpriced
	sort.Strings(s.Unpriced)
	if u.Billed.Known && total.Status != Unpriced {
		s.Unattributed = u.Billed.USD - total.USD
		s.UnattributedKnown = true
	}
	return s
}
package config

import "gopkg.in/yaml.v3"

// AgentUsageConfig holds the settings of the :agent-usage view. It has no
// default and no migration: an empty section is never written to the file.
type AgentUsageConfig struct {
	// Prices maps a model name, kept exactly as written, to its price per
	// million tokens. Validation (negative, NaN, Inf) belongs to the pricing
	// package, not to the loader.
	Prices map[string]ModelPrice `yaml:"prices,omitempty"`
}

// ModelPrice is the price of one model, per rate. Each rate is optional.
type ModelPrice struct {
	Input        Rate `yaml:"input,omitempty"`
	Output       Rate `yaml:"output,omitempty"`
	CacheWrite5m Rate `yaml:"cache_write_5m,omitempty"`
	CacheWrite1h Rate `yaml:"cache_write_1h,omitempty"`
	CacheRead    Rate `yaml:"cache_read,omitempty"`
}

// RateState tells whether a Rate was absent, unreadable, or a number.
type RateState int

const (
	// RateMissing means the key was absent (or null) in the file.
	RateMissing RateState = iota
	// RateInvalid means the value was not a number (text, list, map, bool).
	RateInvalid
	// RateSet means the value decoded as a number, whatever the number is.
	RateSet
)

// Rate is a tolerant price: a badly typed value costs its own entry, never
// the load of the whole context. The zero value is RateMissing.
type Rate struct {
	state RateState
	value float64
	raw   string     // text of an invalid scalar, written back unchanged
	node  *yaml.Node // copy of an invalid non-scalar (list, map, alias), written back unchanged
}

// Value returns the number and the state; the number is meaningful only for
// RateSet.
func (r Rate) Value() (float64, RateState) { return r.value, r.state }

// IsZero reports a missing rate so that omitempty skips it.
func (r Rate) IsZero() bool { return r.state == RateMissing }

// UnmarshalYAML never returns an error: anything that is not an int or float
// scalar becomes RateInvalid.
func (r *Rate) UnmarshalYAML(node *yaml.Node) error {
	*r = Rate{state: RateInvalid}
	if node.Kind != yaml.ScalarNode {
		cp := *node
		r.node = &cp
		return nil
	}
	r.raw = node.Value
	if tag := node.ShortTag(); tag != "!!int" && tag != "!!float" {
		return nil
	}
	var f float64
	if err := node.Decode(&f); err != nil {
		return nil
	}
	*r = Rate{state: RateSet, value: f}
	return nil
}

// MarshalYAML writes the number back, or an invalid value as it was read: the
// original node for a list, map or alias, the raw text for a scalar.
func (r Rate) MarshalYAML() (any, error) {
	if r.state == RateSet {
		return r.value, nil
	}
	if r.node != nil {
		return r.node, nil
	}
	return r.raw, nil
}
